class Solution { private lateinit var toppings:IntArray;private var target=0;private var best=0;private fun update(cost:Int){val difference=kotlin.math.abs(cost-target);val bestDifference=kotlin.math.abs(best-target);if(difference<bestDifference||difference==bestDifference&&cost<best)best=cost};private fun dfs(index:Int,cost:Int){if(index==toppings.size){update(cost);return};dfs(index+1,cost);dfs(index+1,cost+toppings[index]);dfs(index+1,cost+2*toppings[index])};fun closestCost(baseCosts:IntArray,toppingCosts:IntArray,target:Int):Int{toppings=toppingCosts;this.target=target;best=baseCosts[0];for(base in baseCosts)dfs(0,base);return best} }
